def round_existing_amounts(apps, schema_editor):
    """Arrondit au centime les montants déjà enregistrés (anciens float du
    type 9900.709999999997)."""
    cent = Decimal("0.01")
    specs = [
        ("Wallet", ["balance"]),
        ("Transaction", ["amount"]),
        ("PaymentRequest", ["amount", "amount_local"]),
        ("ReferralTransaction", ["amount"]),
    ]
    for model_name, fields in specs:
        model = apps.get_model("monetisation", model_name)
        batch = []
        for obj in model.objects.all().iterator():
            for field in fields:
                value = getattr(obj, field)
                if value is not None:
                    setattr(obj, field, Decimal(str(value)).quantize(cent, rounding=ROUND_HALF_UP))
            batch.append(obj)
        if batch:
            model.objects.bulk_update(batch, fields, batch_size=500)


